$ErrorActionPreference='Stop'; $root=(Resolve-Path (Join-Path $PSScriptRoot '..')).Path; $task=Join-Path $root 'examples/tasks/bugfix.json'; $sessionPath=Join-Path $env:TEMP 'runtime-session.json'; & powershell -NoProfile -File (Join-Path $root 'bin/new-runtime-session.ps1') -TaskPath $task|Set-Content $sessionPath; & powershell -NoProfile -File (Join-Path $root 'bin/validate-runtime-policy.ps1') -SessionPath $sessionPath -Tools Read|Out-Null; 'RUNTIME_POLICY_TESTS_OK'
